pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space" classes.
    let residue = post_residual % 10;
    // Residues 1..9 (non-zero, small) are worst: nearly nothing fits later.
    if post_residual > 0 {
        if residue != 0 && residue <= 4 {
            score += 25.0 * (5 - residue) as f64; // tiny unusable slivers
        } else if residue != 0 {
            score -= 4.0 * residue as f64; // larger residues more reusable
        } else {
            score -= 20.0; // exact multiple of 10: excellent harmonic class
        }
    } else {
        score -= 60.0; // perfect closure
    }

    // Integer-division thresholds: how many "average items" (size ~25) fit post-placement.
    let slots = post_residual / 25;
    score -= 15.0 * slots as f64;

    // Capacity fraction coupling: fraction of bin still free after placement.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * (0.5 - frac).abs(); // prefer residuals near half capacity

    // Lookahead harmonic match: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact/modulo fit bonus
            let r = post_residual % next_item_size;
            if r == 0 { score -= 30.0; } else { score -= 10.0 * (1.0 - r as f64 / next_item_size as f64); }
        } else {
            // next item cannot fit here: penalize more if we also leave bad residue
            score += 8.0;
        }
    } else {
        // last item: closing bins is free
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 120.0 - 10.0 * congestion;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 20.0; // big next item: fresh bin is strategic
        }
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64; // smallest item possible
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 25.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving a gap just below the next item (blocks lookahead item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += ((next_item_size - post_residual) as f64) * 1.5;
    }

    // Reward bins that can also fit the lookahead item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bins pressure: prefer already-open bins over opening new ones,
    // scaled by how crowded the bin already is.
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * fill_frac);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Slight stream-progression pressure to consolidate early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalty
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving residual that exactly fits the next item poorly:
    // if next item fits in post_residual, this bin stays attractive (chain packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // extra reward if next item then fills bin almost completely
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // residual too small for next item: dead-space penalty scaled by how dead it is
        let deadness = post_residual as f64 / next_item_size.max(1) as f64;
        score += 10.0 * deadness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        // base cost of opening a bin, reduced early (exploration) or when congested
        score += 90.0 - 50.0 * (1.0 - progress) - 8.0 * congestion;
        // if no open bin can fit the item at all, opening is mandatory-ish
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // don't open a new bin for a small item
        score += 0.6 * (bin_capacity as f64 - item_size as f64);
    }

    // Mild preference for bins below mean residual (balance the pool)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Late-stream: push toward filling bins completely
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

