pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post-residual by capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Penalize creating dead space that no plausible item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual as f64 - next_item_size as f64) * 0.3;
        } else {
            score += 6.0; // next item won't chain here
        }
        // Exact chain fit: perfect packing pair
        if next_item_size == post_residual {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoiding fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a long-term investment.
    // Only attractive when existing bins have poor fit quality or are few.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 40.0 - 15.0 * progress;
        // If current item fits poorly anywhere (large item, high mean residual => scattered bins),
        // opening fresh is more attractive.
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        new_bin_score -= fit_ratio * 15.0;
        new_bin_score += (mean_residual - post_residual as f64).abs() * 0.1;
        // If many bins are open and fragmented, a fresh bin consolidates future items.
        new_bin_score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        score = score.min(new_bin_score) - 5.0;
    }

    // Global state: prefer filling bins whose residual is close to the mean
    // (balanced depletion keeps options open).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Mild preference for bins with larger residual late in the stream
    // (consolidate into emptier bins when near the end).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual as f64 / bin_capacity as f64) * progress * 5.0;

    // Slight penalty for spreading across many bins when few items remain.
    if total_items > step_index {
        let remaining = (total_items - step_index) as f64;
        if remaining < 5.0 {
            score += open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: post_residual can still host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.0;
        // Tighter leftover after hosting next item is better.
        score -= (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Compare post_residual against mean residual across open bins.
    score -= (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize tiny unusable residuals (dead space) unless near stream end.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Late in stream: consolidate into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 30.0 * progress;
    }

    score
}

