pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, smoothly scaled by progress
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear coupling: penalize large residuals quadratically as stream progresses
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual relative to item) with smooth saturation
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * fill_ratio * 10.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward bins whose post-residual can host the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr - nx) / cap;
        if fit_next >= 0.0 {
            score -= 8.0 * (1.0 - fit_next) * (1.0 - 0.5 * progress);
        } else {
            score += 5.0 * (-fit_next) * cap / 100.0;
        }
    }

    // New-bin candidate: penalize opening bins early, more leniently as progress grows
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + mean_residual * 0.1;
    }

    // Mild dispersion penalty: avoid drifting far from mean residual
    score += ((pr as f64 - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item-size classes (10/20/25/50) are more reusable.
    let reusable = (post_residual % 10 == 0) as f64 * 6.0
        + (post_residual % 20 == 0) as f64 * 4.0
        + (post_residual % 25 == 0) as f64 * 3.0
        + (post_residual % 50 == 0) as f64 * 5.0;
    score -= reusable;

