    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 10.0;
        }
        // leftover divisible by next item size class suggests future pairing
        if next_item_size <= post_residual && post_residual % next_item_size.max(1) == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin harmonizes well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 15.0 - 20.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Tightness bonus: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Early in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0);

    // Prefer bins whose residual deviates from the mean (specialization).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for typical future items are wasted.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual < min_useful {
        score += 50.0; // nearly-full bin, tiny gap: good, strongly favored
    } else if post_residual < next_item_size && next_item_size > 0 {
        // gap unusable by the lookahead item
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 + 0.5 * gap;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // but when few bins are open, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (1.0 - progress) * 0.3;

    // New-bin candidate: only attractive when current bins fit poorly
    // (large dead space would be created) or item is huge.
    if bin_residual == bin_capacity {
        let waste_elsewhere = (post_residual as f64) - (bin_residual - item_size) as f64; // =0 for new bin
        let _ = waste_elsewhere;
        let best_possible = item_size as f64;
        let poor_fit = if bin_residual >= item_size && post_residual > 0 {
            (post_residual as f64) / best_possible
        } else { 0.0 };
        // base cost of a new bin, discounted if the fit elsewhere is bad
        score += 25.0 - 20.0 * (poor_fit - 1.0).max(0.0).min(1.0);
        // late in stream, slightly cheaper to open bins since leftovers are less reusable
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is close to mean (keep residuals uniform for future packing)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item can exactly fill the
    // post-residual, this is an ideal chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits too: mild bonus proportional to remaining slack.
            score -= 3.0 * (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        } else {
            // Next item cannot fit in post-residual: penalize dead space,
            // worse when the leftover is small and unusable.
            let waste = (next_item_size - post_residual) as f64;
            score += 2.0 * waste / (bin_capacity as f64);
        }
    }

    // Compare residual against mean residual across open bins: prefer bins
    // that leave less residual than average (consolidating space).
    score += 1.5 * ((post_residual as f64) - mean_residual) / (bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize creating tiny unusable slivers (0 < post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }
    // Perfect closure is excellent.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Early in the stream, be slightly more willing to open/keep bins loose;
    // late in the stream, pack tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 2.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let cap = bin_capacity as f64;
    let frac_used = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * frac_used * frac_used;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.4 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Lookahead: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 18.0 * (1.0 - nxt / cap);
            // bonus if next item nearly fills what remains
            let gap = post_residual as f64 - nxt;
            if gap <= 10.0 { score -= 12.0; }
        } else {
            // next item won't fit here: mild penalty proportional to wasted potential
            score += 6.0 * (nxt / cap);
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless
    // current fit is poor or many bins are already open with slack.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // if open bins are collectively full, new bin is fine
        if mean_residual < 15.0 { score -= 12.0; }
        // many open bins with slack: discourage
        score += (open_bins_count as f64).min(10.0) * 0.8;
    } else {
        // slight preference for filling already-open bins as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * progress;
    }

    // Prefer bins below mean residual (consolidate slack).
    score += 0.15 * ((post_residual as f64) - mean_residual).max(-40.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large post_residual quadratically).
    // Late: larger residuals matter less; scale down the quadratic penalty.
    let quad = (pr / cap).powi(2);
    score += quad * (1.0 - progress) * 2.0;

    // Cubic interaction: penalize mid-range dead space more as stream progresses,
    // smooth in progress via a bell-shaped polynomial weight.
    let bell = 4.0 * progress * (1.0 - progress);
    let mid_waste = (pr / cap - 0.5).powi(2);
    score += bell * mid_waste * 1.5;

    // Lookahead coupling: reward leaving room for the next item (smooth polynomial).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx) / cap;
        if fit_gap >= 0.0 {
            score -= (fit_gap - (fit_gap).powi(3)) * 0.8;
        } else {
            score += 0.5 * (-fit_gap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Slight preference for reusing open bins vs opening new ones,
    // modulated by mean residual (crowded bins -> less pressure).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 0.25 + 0.5 * progress;
    } else {
        score -= 0.1 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes (mod 10) are gold.
    let class = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if class == 0 {
        score -= 25.0; // leaves a round slot, easy to fill later
    } else if class <= 3 {
        score += 12.0; // tiny dead space, hard to reuse
    }

    // Integer-division thresholds: penalize residuals in "awkward" bands.
    let q = post_residual / 25; // 0..4
    match q {
        0 => score += 8.0,   // <25 residual mostly dead
        1 => score -= 4.0,   // 25..49 usable by mid items
        2 => score -= 10.0,  // 50..74 very reusable
        _ => score -= 6.0,
    }

    // Coupling with lookahead item: reward residuals that fit next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_slack = post_residual - next_item_size;
        if next_slack % 10 == 0 { score -= 18.0; }
        if next_slack <= 5 { score -= 10.0; }
    } else if next_item_size > 0 {
        score += 6.0; // next item cannot reuse this bin's remainder
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 40.0 + fragmentation * 0.3 - 20.0 * progress;
    }

    // Mild tie-break toward tighter bins via mean residual comparison.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it cannot fit even the smallest plausible item (1..=10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Penalize residuals that can't fit the lookahead item (k=2) if it would otherwise strand space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Pull toward mean residual: prefer bins whose fill matches the average state.
    score += 0.25 * ((bin_residual as f64) - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, only chosen when all open bins score badly.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.2 * open_bins_count as f64;
        // If next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size < 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward exact match with next item ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect: next item exactly fills this bin afterwards
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: good chain
            let diff = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: dead space relative to lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 50.0).min(2.0);
        }
    } else {
        // Last item: just minimize post residual
        score += 0.0;
    }

    // --- Relative residual vs mean residual across open bins ---
    // Prefer bins whose post residual stays near/below the mean (balanced packing)
    let post = post_residual as f64;
    score += 0.15 * (post - mean_residual);

    // --- Tight fit reward: small post residual is good, but avoid tiny slivers ---
    if post > 0 && post < 10 {
        // Unusable sliver: penalize dead space
        score += 6.0;
    } else if post == 0 {
        // Perfect fill now
        score -= 25.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item fits poorly anywhere
        // else (many bins but few fitting) or stream is early.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_elsewhere = if fitting_bins_count > 0 {
            (fitting_bins_count as f64 / open_bins_count.max(1) as f64) < 0.35
        } else {
            true
        };
        if poor_fit_elsewhere || open_bins_count == 0 {
            // Base cost of a fresh bin plus lookahead consideration
            score = 45.0 + post as f64 * 0.3;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 10.0;
            }
            if progress > 0.8 {
                score += 10.0; // late in stream, avoid proliferating bins
            }
        } else {
            // Prefer existing bins: make new bin unattractive
            score += 60.0;
        }
    }

    // --- Slight preference for bins with less residual before placement (denser bins) ---
    score += 0.05 * bin_residual as f64;

    // --- Tie-break with stream position noise-free deterministic nudge ---
    score += (step_index % 3) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that cannot plausibly hold the next item.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Residual can host the next item: reward it proportionally.
            score -= 0.20 * (post_residual as f64 - next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure term: when many bins are open, discourage opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when pressure is high or mean residual is large.
        score += 8.0 + 3.0 * open_pressure + 0.10 * mean_residual;
        // But if no open bin fits well (post_residual of alternatives unknown),
        // soften penalty when mean residual is small (bins nearly full).
        if mean_residual < 10.0 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins when pressure is high.
        score -= 0.5 * open_pressure;
    }

    // Time horizon: early in the stream, be conservative (favor tight packing);
    // late in the stream, prioritize closing out bins with small residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.15 * post_residual as f64;
    score -= (1.0 - progress) * 2.0;

    // Prefer bins whose residual is already close to the mean (harmonized packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 2.0 * norm_post * norm_post);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late, punish dead space quadratically
    let progress_coupling = 1.0 + 3.0 * progress * progress;
    score += norm_post * norm_post * cap * progress_coupling;

    // Smooth penalty when post-residual becomes unusable (below min item 1)
    if pr > 0.0 {
        score += (cap / pr) * 0.5 * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_gap = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference for fuller bins relative to the fleet mean residual
    score += (mean_residual - pr) * 0.05;

    // Slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual ---
    // Class bins into capacity fractions: perfect fit (0), tiny gap (1..=9),
    // medium gap (10..=29), large gap (>=30). Reward tight fits nonlinearly.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c;

    if post_residual == 0 {
        score -= 1000.0; // perfect closure — always best
    } else if post_residual <= bin_capacity / 10 {
        score -= 40.0 * (1.0 - frac); // small usable gap, strong reward
    } else if post_residual <= bin_capacity / 4 {
        score -= 10.0;
    } else {
        // large dead space: penalize quadratically above quarter capacity
        score += 8.0 * frac * frac * c;
    }

    // --- Modulo harmony: does next item divide the post residual evenly? ---
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            let div = post_residual / next_item_size;
            let rem = post_residual % next_item_size;
            if rem == 0 {
                // next item(s) tile the gap perfectly — big reward
                score -= 60.0 + 5.0 * div as f64;
            } else if rem <= bin_capacity / 10 {
                score -= 25.0; // leaves a small usable gap after next item
            } else {
                score += (rem as f64) * 0.5; // wasted space after next item
            }
        } else {
            // next item cannot use this gap at all — gap likely becomes dead
            score += (next_item_size as f64) * 0.3;
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins are crowded
        // and the current item is large relative to capacity.
        let crowding = mean_residual / c;
        let pressure = 1.0 - crowding;
        score = 0.5 * c + pressure * 30.0 - (item_size as f64) * 0.4;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // --- Stream progression: late in the stream, consolidate aggressively ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Prefer bins tighter than the mean (best-fit flavor with adaptive pull)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    // A residual gap that cannot fit even the smallest plausible item (<=10)
    // is pure waste; weight it quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        score -= 8.0; // perfect fit is excellent
    } else {
        // Larger gaps are more reusable; damp their contribution.
        score -= 2.0;
    }

    // Penalize gaps that cannot fit the lookahead item (k=2) if they also
    // cannot fit typical small items — likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.15;

    // Last-chance bin bonus: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits,
    // i.e., mean residual is small relative to item size.
    if bin_residual == bin_capacity {
        let poor_fit = (mean_residual - item_size as f64) < 5.0;
        if poor_fit && open_bins_count > 0 {
            score -= 3.0;
        } else {
            score += 10.0; // prefer existing bins otherwise
        }
    }

    // Slight preference for tighter existing fits via mean residual coupling.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item still fits in the post-residual space.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // Next item does NOT fit: dead space penalty proportional to wasted gap.
    else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual wastes capacity relative to the fleet.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * 2.0;
        // Early in stream, new bins are cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 100.0;
    }

    // Slight preference for tighter bins (less residual before placement).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalty
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving residual that exactly fits the next item poorly:
    // if next item fits in post_residual, this bin stays attractive (chain packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // extra reward if next item then fills bin almost completely
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // residual too small for next item: dead-space penalty scaled by how dead it is
        let deadness = post_residual as f64 / next_item_size.max(1) as f64;
        score += 10.0 * deadness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        // base cost of opening a bin, reduced early (exploration) or when congested
        score += 90.0 - 50.0 * (1.0 - progress) - 8.0 * congestion;
        // if no open bin can fit the item at all, opening is mandatory-ish
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // don't open a new bin for a small item
        score += 0.6 * (bin_capacity as f64 - item_size as f64);
    }

    // Mild preference for bins below mean residual (balance the pool)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Late-stream: push toward filling bins completely
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear post-residual shaping: penalize large dead space superlinearly
    let post_frac = post / cap;
    score += 12.0 * post_frac * post_frac * post;

    // Smooth interaction: waste is worse late in the stream
    let late = progress * progress;
    score += 25.0 * late * post_frac;

    // Tight fit reward (quadratic in item share)
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill * fill;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let nxt = next_item_size as f64 / cap;
        score -= 10.0 * nxt * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 - post) / cap;
    }

    // Prefer fuller bins relative to mean residual (smooth sigmoid-like term)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev / (1.0 + (-dev).exp());

    // Mild preference to reuse existing bins vs opening new ones
    score += 2.0 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: bins whose residual falls in "usable"
    // classes (multiples of common small sizes) are more valuable to keep.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 { 0.0 }
        else if pr <= 10 { -8.0 }          // small dead space, still usable
        else if pr % 10 == 0 { -6.0 }      // round residual, easy to fill
        else if pr % 5 == 0 { -3.0 }
        else if pr % 2 == 0 { -1.0 }
        else { 4.0 };                       // odd residual: harder to pair
    score += harmonic_bonus;

    // Penalize residuals that no plausible future item (1..=100) can pair with well
    if pr > 0 && pr < 10 {
        score += 5.0; // awkward sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            score -= 12.0 * (1.0 - waste as f64 / 100.0);
        }
        // next item is large: prefer bins with big post_residual
        if next_item_size > 50 && pr >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless their residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheap; later, prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins whose residual is far below the mean (tighten stragglers)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Many open bins: encourage consolidation into already-open bins
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
