pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Partial lookahead fit: reward proportional to how much of the leftover is used.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill_ratio;
            // Penalize leaving a tiny unusable sliver after the lookahead item.
            let sliver = post_residual as f64 - next_item_size as f64;
            if sliver > 0.0 && sliver < 5.0 {
                score += 18.0;
            }
        } else {
            // Next item cannot fit here: mild penalty so bins that chain get priority.
            score += 8.0;
        }
    }

    // Exact-fit reward for the current item.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Small dead space is bad unless next item can use it (already rewarded above).
        score += 12.0;
    }

    // Prefer tight packing relative to mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    // or the item simply doesn't chain well.
    if bin_residual == bin_capacity {
        let avg_fullness = bin_capacity as f64 - mean_residual;
        let pressure = (avg_fullness / bin_capacity as f64).clamp(0.0, 1.0);
        score += 55.0 * (1.0 - pressure);
        if next_item_size > 0 && next_item_size <= item_size {
            score += 10.0; // new bin wastes the lookahead chain opportunity
        }
    }

    // Early in the stream, be slightly more willing to keep bins balanced.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but zero is best.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize leaving dead space that nothing can use later.
        let dead = post_residual < 10;
        if dead {
            score += 15.0; // tiny unusable sliver is wasted capacity
        }
        // Non-linear penalty on large post_residual (wasteful fit).
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + 0.2 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize more when post_residual is large
            score += 0.1 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only when
    // existing fits are poor (large post_residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins, scaled by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 45.0 + 20.0 * progress;

        // If item is large relative to capacity, new bin gives good long-term room.
        if item_size >= bin_capacity / 2 {
            new_bin_score -= 10.0;
        }
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            new_bin_score += 15.0;
        }
        // If open bins have plenty of mean residual, prefer using them.
        if mean_residual > item_size as f64 * 1.5 {
            new_bin_score += 10.0;
        }
        score = new_bin_score;
    } else {
        // Slight preference for fuller bins (best-fit flavor) among open bins.
        score -= 0.3 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * norm_pr + 0.5 * norm_pr * norm_pr);

    // Reward tight fits smoothly (small post_residual)
    score -= 0.6 * (1.0 - norm_pr).powi(2) * (1.0 - progress);

    // Penalize dead space more as stream progresses (fewer chances to fill it)
    score += 0.4 * progress * norm_pr * norm_pr;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.5;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.5 * (nxt / cap) * (1.0 - (pr - nxt) / cap);
        } else {
            score += 0.3 * (nxt - pr) / cap;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * (open_bins_count as f64).ln();

    // Pull toward mean residual to keep bins balanced
    score += 0.2 * (norm_pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: crush the score.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover space: small leftovers are dead space.
    // Class the post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted
    if frac <= 0.05 {
        score -= 60.0; // nearly perfect fill
    } else if frac <= 0.15 {
        score -= 20.0;
    } else if frac <= 0.30 {
        score += 15.0;
    } else {
        score += 45.0; // large dead space penalty
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common small item sizes (e.g. multiples of 10) are reusable.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 12.0;
    }
    if pr % 5 == 0 {
        score -= 4.0;
    }
    // Harmonic classes: residuals divisible by 20 or 25 pair well with mid items.
    if pr % 20 == 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 && next_item_size <= pr {
        if next_item_size == pr {
            score -= 200.0;
        } else {
            let after2 = pr - next_item_size;
            // integer division thresholds on the two-step leftover
            if after2 <= 10 {
                score -= 40.0;
            } else if after2 <= 25 {
                score -= 15.0;
            }
            if after2 % 10 == 0 {
                score -= 8.0;
            }
        }
    } else if next_item_size > pr {
        // next item cannot use this leftover: penalize proportionally
        score += 10.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: opening a bin is expensive; make empty bin moderately
    // unattractive unless the item simply does not fit well anywhere.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
        // but for large items relative to capacity, a fresh bin is fine
        if item_size * 4 >= bin_capacity * 3 {
            score -= 35.0;
        }
    }

    // Slight early-stream preference for consolidation later on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
