    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // NEW-BIN DECISION: open a fresh bin only when this item is large enough
    // that pairing it with a fresh bin leaves useful space for the next item,
    // or when the best existing fit is poor (high post_residual relative to item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > mean_residual * 0.9
            && fitting_bins_count > 0
            && item_size < bin_capacity / 2;
        // Early in stream or when all open fits are bad, new bins are cheap.
        let base = if poor_fit { 60.0 } else { 170.0 };
        score += base + open_bins_count as f64 * 2.0 + progress * 100.0;
        // If the next item fits exactly into a fresh bin after this placement,
        // opening a new bin is attractive: reduce the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0;
        }
    }

    // Slight preference for tighter bins (less residual before placement).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Reward bins whose post-residual is a "usable" size (>= next item),
    // scaled by how tight the fit is, to encourage near-perfect chains.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
