pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Strong reward for perfect fill (dominant signal).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: reward residuals that exactly or nearly fit next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 560.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.6;
            // Bonus for remaining space still usable for typical items.
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3 + if gap > 25.0 { gap * 0.18 } else { 0.0 };
        }
    }

    // Scarcity-aware penalty for stranded residual that can't host next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let scarcity = 1.0 + 4.0 / fitting_bins_count.max(1) as f64;
        score += (post_residual as f64 / bin_capacity as f64) * 8.0 * scarcity;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < item_size {
        score += 14.0;
    }

    // Dead-space ratio shaping (borrowed & tuned from best).
    let dead = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 {
        if dead < 0.1 {
            score -= 6.0 * (0.1 - dead) * 10.0;
        } else if dead > 0.5 && next_item_size > 0 && post_residual < next_item_size {
            score += 18.0 * (dead - 0.5);
        } else if dead > 0.35 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * (dead - 0.35) * (0.5 + progress);
        }
    }

    // Unreachable-gap penalty scaled by bin scarcity.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unreachable = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 9.0 * unreachable * (1.0 + (open_bins_count.max(1) as f64).recip());
    }

    // Mild fill pressure.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Open-bin pressure scaled by progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual pull.
    score += 0.25 * ((bin_residual as f64) - mean_residual).abs();

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalized, especially when open bins are tight or item is large.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = item_size as f64 / bin_capacity as f64;
        let tight = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 40.0 + 65.0 * (1.0 - pressure) * tight;
        if next_item_size > 0 && next_item_size < 20 {
            score -= 10.0;
        }
    }

    score
}

