    // (item fits, and the leftover residual exactly hosts the next item).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-step chain: consume residual fully next step
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // mild reward proportional to closeness of the chain match
            score -= (30.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot use this residual: penalize dead space,
            // harder when residual is small (unusable sliver)
