            let small_penalty = if dead < 10.0 { 25.0 } else { 0.0 };
            score += 0.35 * dead + small_penalty;
        }
    } else {
        // last item: prefer minimal leftover
        score += 0.2 * post_residual as f64;
    }

    // Compare against mean residual: placing into a bin with residual far
    // below mean (tight bin) is good; far above mean wastes space.
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins are already open and one fits well
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // but allow new bin if lookahead chain is hopeless in all bins
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Slight preference to keep residual near multiples of common item sizes
    let mod10 = post_residual % 10;
    if mod10 != 0 {
        score += 0.5 * mod10 as f64;
    }

    score
}

