    if next_item_size > 0 && post_residual == next_item_size {
        score -= 560.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward fitting the lookahead item; sharpen the preference for tight leftovers.
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 + slack * 0.9;
        // Extra reward when the slack itself could host another small item later.
        if slack > 0 && slack <= 12 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual can't hold next item: penalize stranded gap, scaled by how
        // likely the next item is large relative to capacity.
        let gap = (next_item_size - post_residual) as f64;
        let next_frac = next_item_size as f64 / bin_capacity as f64;
        score += gap * (0.3 + 0.35 * next_frac) + if gap > 25.0 { gap * 0.18 } else { 0.0 };
    }

    // Mild preference for fuller bins.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Reward leaving usable space for the lookahead item on well-filled bins.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: expensive, but cheaper when open bins are highly fragmented
    // and the item is large (opening fresh space avoids stranding a big item).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = item_size as f64 / bin_capacity as f64;
        let tight = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let frag = (fitting_bins_count as f64 / open_bins_count.max(1) as f64).clamp(0.0, 1.0);
        let hard = 1.0 - frag;
        score += 40.0 + 65.0 * (1.0 - pressure) * tight - 30.0 * hard * pressure;

        // Additional guard: if any open bin leaves post_residual >= next item, opening
        // a new bin wastes that space — penalize more strongly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0 + (post_residual - next_item_size) as f64 * 0.4;
        }
    }

    // Penalize creating a gap that strands both this item's context and the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < item_size {
        score += 14.0;
    }

    // Dead-space shaping by relative residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 {
        if dead < 0.1 {
            score -= 6.0 * (0.1 - dead) * 10.0;
        } else if dead > 0.5 && next_item_size > 0 && post_residual < next_item_size {
            score += 18.0 * (dead - 0.5);
        } else if dead > 0.35 {
            score += 10.0 * (dead - 0.35) * (0.5 + progress);
        }
    }

    // Unreachable-gap penalty scaled by fragmentation of the bin population.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unreachable = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 9.0 * unreachable * (1.0 + (open_bins_count.max(1) as f64).recip());
    }

