    if post_residual > 0 && post_residual < 6 {
        score += 8.0 * (6 - post_residual) as f64;
    }

    // Exact-fit reward: residual exactly consumed by item leaves nothing stranded.
    if post_residual > 0 && post_residual == item_size.min(bin_residual) && bin_residual >= item_size {
