    }

    // NEW: avoid stranding residuals smaller than any plausible future item when the
    // stream is deep — tiny residuals are almost always dead space.
    if post_residual > 0 && post_residual < 10 && progress > 0.5 {
        score += 6.0 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

