    let mean_r = mean_residual / bin_capacity as f64;
    score += 15.0 * pr2 * (1.0 - mean_r) * (1.0 + prog2);

    // Lookahead coupling: reward bins whose post_residual still fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs();
