        score += 10.0 * pr2 * (gap / bin_capacity as f64).max(0.0) * (1.0 - soft.abs() * 0.0 + 0.0);
    }

    // Last-chance bonus: smooth ramp as fitting bins become scarce
    let scarcity = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };
