    }

    // Coupled lookahead pair-fit: if both this item and the next can exactly fill
    // two consecutive placements, strongly reward.
    if next_item_size > 0 && bin_residual >= item_size {
        let r1 = bin_residual - item_size;
        if r1 == next_item_size {
            score -= 20.0;
        } else if r1 > next_item_size && r1 - next_item_size < 8 {
            score -= 10.0;
        }
    }

