    // item wastes the bin almost entirely; penalize proportionally to regret.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let regret = (next_item_size - post_residual) as f64;
        if regret <= 12 {
            score += 12.0 - regret * 0.5;
        }
    }

    // NEW: fragmentation-aware waste discount — when many bins fit the item,
    // slight extra post_residual is cheap; when few fit, demand near-perfect fits.
