        let scarcity = 1.0 - (fitting_bins_count as f64 / open_bins_count.max(1) as f64);
        let waste = post_residual as f64;
        score += waste * 0.08 * scarcity - waste * 0.04 * (1.0 - scarcity);
    }

    // NEW: mid-stream exactness bonus — reward near-closed bins slightly more
    // in the middle of the stream, where consolidation gains compound.
    if post_residual > 0 && post_residual <= 10 && progress > 0.25 && progress < 0.85 {
        score -= 5.0;
    }

    score
}

