    // Many open bins: prefer consolidating into existing bins (avoid fragmentation).
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += open_pressure * 2.0;

    // Mean residual coupling: when mean residual is low, tight fits matter more.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (mean_residual / bin_capacity as f64) * (1.0 - t) * 5.0;

    // Time horizon: late in the stream, be more conservative with new bins.
