        // New-bin candidate: penalize early, allow late when residuals are fragmented.
        score += 20.0 * (1.0 - t);
        if mean_residual < item_size as f64 {
            score -= 15.0 * t;
        }
        // Never open a new bin when the item fits snugly somewhere else.
        if post_residual == 0 {
            score += 100.0;
        }
