pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Dead space: small but unusable for the next item.
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can still host the next item after this placement.
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, be more willing to fill existing bins densely;
    // later, avoid fragmenting many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.25 * post_residual as f64;

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize extreme outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Penalize bins that are already crowded among many open bins
    // (encourages consolidation when many bins are open).
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).ln() * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: make it costly unless the item fits poorly everywhere.
    // An empty bin has large post_residual, so add an explicit opening penalty
    // that shrinks when the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - fill_ratio);
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post-residual with stream progress.
    // Early on (progress ~ 0): mild preference for low post-residual.
    // Later (progress ~ 1): stronger penalty on large wasted residual.
    let w_lin = 1.0 + 1.5 * progress;
    let w_quad = 2.0 * progress * progress;

    let mut score = pr * w_lin + (pr * pr / cap) * w_quad;

    // Smoothly increasing penalty for residual that cannot fit a typical next item.
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - pr).max(0.0) / cap;
        score += 12.0 * gap * gap * (0.5 + progress);
        // Reward if post-residual still fits the lookahead item.
        let fits_next = (pr >= next) as i32 as f64;
        score -= 4.0 * fits_next * (1.0 - progress);
    }

    // Dead-space penalty: residual too small for any plausible item (min size ~1).
    let unusable = ((1.0 - norm_pr).max(0.0) - (1.0 - (10.0 / cap))).max(0.0);
    let dead = ((10.0 - pr) as f64).max(0.0) / 10.0;
    score += 25.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // other bins fit and progress is high (closing out bins is better late).
    if bin_residual == bin_capacity {
        let fits_elsewhere = (fitting_bins_count > 0) as i32 as f64;
        let openness = (open_bins_count as f64 / (1.0 + mean_residual / cap).max(1.0)) / 10.0;
        score += (15.0 + 20.0 * progress) * fits_elsewhere + 5.0 * (1.0 - fits_elsewhere) + 3.0 * openness;
        // A fresh bin is attractive if the item is large and current residuals are tight.
        let tight = (mean_residual / cap - norm_pr).max(0.0);
        score -= 10.0 * tight;
    }

    // Mild reward for filling bins tightly relative to the mean residual state.
    score -= 2.0 * (mean_residual - pr) / cap;

    // Smooth diversity term: discourage fragmenting many bins early.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space" classes.
    let residue = post_residual % 10;
    // Residues 1..9 (non-zero, small) are worst: nearly nothing fits later.
    if post_residual > 0 {
        if residue != 0 && residue <= 4 {
            score += 25.0 * (5 - residue) as f64; // tiny unusable slivers
        } else if residue != 0 {
            score -= 4.0 * residue as f64; // larger residues more reusable
        } else {
            score -= 20.0; // exact multiple of 10: excellent harmonic class
        }
    } else {
        score -= 60.0; // perfect closure
    }

    // Integer-division thresholds: how many "average items" (size ~25) fit post-placement.
    let slots = post_residual / 25;
    score -= 15.0 * slots as f64;

    // Capacity fraction coupling: fraction of bin still free after placement.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * (0.5 - frac).abs(); // prefer residuals near half capacity

    // Lookahead harmonic match: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact/modulo fit bonus
            let r = post_residual % next_item_size;
            if r == 0 { score -= 30.0; } else { score -= 10.0 * (1.0 - r as f64 / next_item_size as f64); }
        } else {
            // next item cannot fit here: penalize more if we also leave bad residue
            score += 8.0;
        }
    } else {
        // last item: closing bins is free
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 120.0 - 10.0 * congestion;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 20.0; // big next item: fresh bin is strategic
        }
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-dead zone: residual too small for typical mid/large items.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading residual
    // capacity; encourage filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "tight" — favor finishing it off.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= residual_gap.clamp(0.0, 50.0) * 0.4;

    // New-bin candidate: only attractive when no open bin offers a decent
    // fit (this bin would otherwise be a fresh 100 residual, scored high
    // by the base term, so it loses unless forced).
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64).min(10.0);
        // If nothing else fits, opening a new bin is the right move.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
