pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: minimize wasted space -> post_residual already penalizes loose fits.

    // Strong reward for tight fits (small dead space relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: if the next item can fit into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if next item fills the remaining space almost exactly.
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving moderately-sized dead space.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: its natural score is high (large post_residual), but
        // add extra penalty scaled by how much residual capacity exists elsewhere.
        let avg_free = if open_bins_count > 0 { mean_residual } else { 0.0 };
        score += 5.0 + 0.15 * avg_free;
        // But soften the penalty late in the stream or when item is large (hard to place).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mild penalty for creating residuals that are awkwardly small (unusable dead space),
    // i.e., post_residual in a "dead zone" where few future items fit.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 12.0; // tiny slivers are nearly useless
    } else if pr >= 10.0 && pr <= 20.0 {
        score += 4.0; // small residual only fits small items
    }

    // Coupling with global state: when many bins are open with high mean residual,
    // prefer consolidating into existing bins (penalize spreading).
    if open_bins_count > 2 {
        let spread = (mean_residual - pr).abs();
        score += 0.05 * spread;
    }

    // Slight time-horizon modulation: early in the stream, be a bit more conservative
    // with tight fills (leave flexibility); late, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fill lookahead: huge reward for perfect residual match with next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 560.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward fitting the next item, penalize leftover slack proportionally.
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.6;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: penalize by the gap size.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.3 + if gap > 25.0 { gap * 0.18 } else { 0.0 };
    }

    // Dead-space avoidance: small unusable residuals are wasted space.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small waste ratio).
    let waste = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste) * 5.0;

    // Last-chance bonus: only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: heavy penalty scaled by open-bin pressure,
    // stream progress, and item pressure.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let pressure = item_size as f64 / bin_capacity as f64;
            let tight = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
            let frag = (fitting_bins_count as f64 / open_bins_count.max(1) as f64).clamp(0.0, 1.0);
            let hard = 1.0 - frag;
            score += 40.0 + 65.0 * (1.0 - pressure) * tight - 30.0 * hard * pressure;
            // If some open bin would leave nearly no waste, strongly discourage new bin.
            if fitting_bins_count > 0 {
                let best_waste = post_residual.min(item_size) as f64;
                if best_waste < bin_capacity as f64 * 0.06 {
                    score += 30.0;
                }
            }
            let progress = step_index as f64 / total_items.max(1) as f64;
            if progress > 0.55 && fitting_bins_count > 0 {
                score += 20.0 * (progress - 0.55) * 2.0;
            }
