    // Small-tail bonus: if placing here leaves a tail that nearly fits the next item.
    if next_item_size > 0 && bin_residual >= item_size {
        let r1 = bin_residual - item_size;
        if r1 > next_item_size {
            let tail = r1 - next_item_size;
            if tail <= 10 {
                score -= 14.0 - tail as f64;
            }
        }
    }

    // Late-stream compaction: penalize large residuals more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.6 {
        score += post_residual as f64 * 0.15 * (progress - 0.6) * 2.5;
    }

    // Prefer residuals close to the mean (consolidation).
    if post_residual > 0 {
        let diff = (post_residual as f64 - mean_residual).abs();
        score -= 4.0 * (1.0 - (diff / bin_capacity as f64).min(1.0));
    }

    // Tiny-tail bonus after fitting next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let tail = post_residual - next_item_size;
        if tail <= 4 {
            score -= 9.0 - tail as f64 * 1.5;
        }
    }

    // Near-miss regret: residual just below next item size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let regret = (next_item_size - post_residual) as f64;
        if regret <= 12 {
            score += 12.0 - regret * 0.5;
        }
    }

    // Exact residual equals item size: perfect fill reward.
    if post_residual > 0 && post_residual == item_size.min(bin_residual) && bin_residual >= item_size {
        score -= 8.0;
    }

    // Trapped residual: too small for anything useful.
    if post_residual > 0 && post_residual < next_item_size && post_residual < item_size {
        score += 14.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), with non-linear saturation
    let mut score = post + 30.0 * (post / cap).powi(3);

    // Smooth polynomial coupling of tightness with stream progress:
    // early on, tolerate imperfect fits; late, demand tight packing.
    let tightness = 1.0 - post / cap;
    score -= 40.0 * progress * tightness * tightness;
    score += 25.0 * (1.0 - progress) * (post / cap).powi(2);

    // Penalize post-residual that is unusably small (dead space) via smooth bump
    let dead = (post / cap - 0.15).powi(2);
    score += 20.0 * (-dead * 40.0).exp() * (1.0 - progress);

    // Lookahead: reward leaving room for the next item (smooth quadratic deficit)
    if next_item_size > 0 {
        let deficit = (next_item_size as f64 - post).max(0.0);
        score -= 12.0 * (1.0 - deficit / cap);
        score += 10.0 * (deficit / cap).powi(2);
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // Alignment with mean residual state
    score += 5.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good, with harmonic class emphasis.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Dead-space classes: residuals that few item sizes (1..=100) can use are bad.
        // Harmonic class: how close post_residual is to a "popular" size quantum.
        let q = pr % 10; // modulo class on the residual
        score += (q as f64) * 0.8; // prefer residuals on multiples of 10

        // Integer-division threshold: residuals <= 20 are nearly dead space for typical items.
        if pr <= 20 {
            score += (21 - pr) as f64 * 0.5; // penalize tiny leftovers
        }
        // Sweet spot: residual in 30..60 is highly reusable.
        if pr >= 30 && pr <= 60 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // reward proportional to closeness, penalize if it leaves another tiny residue
            score -= (20.0 - (slack as f64) * 0.3).max(0.0);
            if slack <= 10 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover at all -> mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity if any open bin
    // fits reasonably; make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 - 10.0;
        // If existing fits are scarce or mean residual is small, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if mean_residual < 15.0 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    }

    // Mild penalty for spreading across many open bins when this bin is already loose.
    if open_bins_count > 4 && post_residual > 50 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fill
    } else if post_residual < 10 {
        // tiny unusable sliver: heavily penalize
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else {
        // Usable gap: mild reward for smaller residual, but reward leaving room
        // for the lookahead item exactly.
        score -= 4.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 120.0;
        } else if next_item_size > 0 && post_residual > next_item_size {
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    let pressure = open_bins_count as f64;
    score -= (pressure.log10() + 1.0) * 6.0;

    // Relative residual vs mean residual: prefer bins below-average residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.35;

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else or open bins are very full on average.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        if fitting_bins_count > 0 && avg_fill < 0.55 {
            // decent fits exist and bins aren't crowded: penalize opening new bin
            score += 150.0;
        } else {
            // crowded or poor fits: mild bonus for fresh bin
            score -= 20.0 + avg_fill * 40.0;
        }
    }

    // Early in stream: be slightly conservative, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += post_residual as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
