pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual strongly favored.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual,
    // this is a perfect chain placement — reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 == next_item_size as i64 {
            score -= 60.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 30.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // Dead space relative to next item: penalize proportionally.
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: leaving this bin far below
    // the mean creates an outlier sliver bin; penalize.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.3 * (-dev);
    } else {
        score -= 0.15 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item is
    // large and would leave a big residual chainable with next item.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64) >= next_item_size as i64 {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual non-linearly.
    score -= 40.0 * (-post_residual as f64 / 12.0).exp();

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in stream, slightly prefer opening fresh bins for
    // large items (long-run packing matters); late, prefer filling existing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New-bin candidate: attractive when item is large relative to capacity
        // or when existing residuals are fragmented.
        score = score * 0.5 + (bin_capacity - item_size) as f64 * 0.6;
        if item_size >= 60 { score -= 20.0 * (1.0 - progress); }
        if open_bins_count as f64 > mean_residual * 0.8 { score -= 10.0; }
    } else {
        // Prefer bins tighter than the mean residual (good fits).
        score += 0.25 * (bin_residual as f64 - mean_residual);
        // Late in stream, reward using open bins aggressively.
        score -= 12.0 * progress;
    }

    // Mild pressure to consolidate when many open bins exist.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
