pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fills (low post_residual), scaled non-linearly.
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (favor moderate residuals);
    // late, pack tightly (favor small residuals aggressively).
    let flex = 0.35 * (1.0 - progress) * (pr / cap) * (1.0 - pr / cap) * 4.0;
    score -= flex * cap * 0.25;

    // Lookahead: reward if next item fits exactly into post_residual,
    // penalize if post_residual is just barely too small for next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 6.0 * (1.0 - (n - pr).abs() / cap) * (0.5 + progress);
        } else {
            score += 3.0 * (1.0 - (pr / n).min(1.0));
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // Penalize opening a new bin when alternatives exist and residual space is plentiful.
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (mean_residual / cap).min(1.0) + 5.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    // Mild diversity bonus: prefer bins deviating from mean residual (keeps spread of sizes).
    score -= 1.5 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Class 0: post_residual divisible by 10 (aligned leftover, easiest to fill later)
    // Class 1: divisible by 5, Class 2: divisible by 2, else awkward.
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -30.0
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -8.0
    } else if pr % 2 == 0 {
        0.0
    } else {
        6.0
    };
    score += class_penalty;

    // Integer-division harmonic: leftover space in "quarter bins" -> dead quarters penalized.
    let quarters = (pr * 4) / bin_capacity;
    score += quarters as f64 * 2.5;

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // fraction of next item covered; reward closeness to exact fit
            let gap = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / cap);
        } else {
            // next item cannot use this residual: penalize by how much residual is dead weight
            score += (pr as f64) * 0.15;
            // extra penalty if residual falls in awkward band (small dead slivers)
            if pr < next_item_size && pr < 20 {
                score += 12.0;
            }
        }
    } else {
        // last item: prefer filling bins tightly
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // neutral base for new bin; penalize when good fits exist among open bins
        score += 45.0;
        if next_item_size > 0 && pr == bin_capacity {
            // empty bin: post_residual == capacity, exact-fit lookahead check
            if next_item_size == bin_capacity {
                score -= 60.0;
            }
        }
        // opening new bins late is costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Prefer bins tighter than average (best-fit flavor via mean residual).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Reward filling bins that are nearly full (small residual fraction).
    let residual_frac = post_residual as f64 / cap;
    score -= 15.0 * (1.0 - residual_frac).powi(2);

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are unusable for typical items.
    if post_residual > 0 {
        let dead = (post_residual as f64) * (1.0 + 40.0 / (post_residual as f64 + 3.0));
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 500.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
