            score += 0.8 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins tighter than average (below-mean residual = better packed).
    score += 0.6 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin, more so as bins accumulate.
    if bin_residual == bin_capacity {
        score += 150.0 + 8.0 * open_bins_count as f64;
    } else {
        // Reward using a partially filled bin proportional to how full it is.
        score -= 0.3 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
