    let post_norm = post / cap;

    // Base: prefer small post residual, with smooth non-linear emphasis.
    let mut score = post + 8.0 * post * post_norm;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late, demand tight packing.
    let tightness = 1.0 + 3.0 * progress * progress;
    score += tightness * post * (1.0 - post_norm);

    // Reward tight fits (small post residual) with a smooth quadratic bonus.
    score -= 12.0 * (1.0 - post_norm) * (1.0 - post_norm);

    // Lookahead: penalize if post residual can't fit next item (wasted space),
    // reward if it matches exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post - nxt) / cap;
            score += 4.0 * gap * gap * cap; // residual mismatch penalty
        } else {
            score += 6.0 * (nxt - post); // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a bin when good fits exist,
    // unless residuals across open bins are small (all bins nearly full).
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - (mean_residual / cap);
        let scarcity = ((fitting_bins_count as f64).ln().max(0.0)) / (1.0 + open_bins_count as f64).ln();
        score += 30.0 + 40.0 * avg_fullness * avg_fullness - 35.0 * scarcity;
    }

    // Mild penalty for spreading across many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64 * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of common item sizes) are favored.
    let post = post_residual;
    if post > 0 {
        let mut harmony = 0.0f64;
        for m in [10u32, 20, 25, 50].iter() {
            if post % m == 0 {
                harmony += 6.0;
            }
        }
        // Near-harmonic: within a small tolerance of a class boundary
        for m in [10u32, 20, 25, 50].iter() {
            let r = post % m;
            if r > 0 && *m - r <= 3 {
                harmony += 2.0;
            }
        }
        score -= harmony;
    } else {
        // Perfect fit: best possible outcome
        score -= 30.0;
    }

    // Penalize dead space that is too small for the smallest plausible item
    if post > 0 && post < 10 {
        score += 12.0;
    }

    // Fraction-of-capacity thresholds on post_residual
    let frac = post as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 4.0; // bin still half open, plenty of room
    } else if frac < 0.1 && post > 0 {
        score += 6.0; // nearly-closed bin, hard to reuse
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 8.0;
            // Bonus if post residual is harmonically compatible with next item
            if post % next_item_size.max(1) == 0 {
                score -= 4.0;
            }
        } else if post > 0 && post >= 10 {
            score += 3.0; // leftover likely wasted relative to lookahead
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish score so it wins only when
    // all open bins are poor fits (high post_residual waste or tiny leftovers).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Stream progression: early on, be slightly more willing to spread items
    // across bins; late in the stream, tighten packing to close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.1;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tight — prefer filling tight bins first.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.2;
    } else {
        score += (-dev) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    } else if post_residual < 20 {
        score += 30.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Perfect fill is heavily rewarded.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, prefer reusing existing bins
    // over opening new ones; when few bins are open, new-bin is less costly.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        score += 25.0 * pressure;
    } else {
        score -= 15.0 * pressure;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement
    // (leaves a useful gap); otherwise penalize leaving a gap sized near the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual >= (next_item_size as f64 * 0.6) as u32 {
            score += 25.0;
        }
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is below mean residual (already "used" bins).
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
