pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item (chains two items perfectly).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit this bin afterwards: penalize
            // proportionally to how much dead space is stranded.
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += 80.0 * dead;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent fitting alternatives exist,
    // unless the new bin enables a perfect fit for the current item.
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score -= 500.0; // new bin with perfect fit is great
        } else if fitting_bins_count > 0 {
            score += 300.0;
        } else {
            score += 50.0; // forced new bin
        }
    }

    // Small late-stream bias: consolidate into fewer bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it if it fits reasonably well,
    // otherwise penalize wasting the closing opportunity.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual <= 15 {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Post-residual too small for next item: penalize dead space proportionally.
            score += 4.0 * (post_residual as f64) / (next_item_size as f64).max(1.0);
        }
    }

    // Global state coupling: prefer filling bins when mean residual is low
    // (bins are already fragmented), prefer spreading when mean residual is high.
    let mean_gap = (bin_residual as f64) - mean_residual;
    score += 0.05 * mean_gap;

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tight;

    // Many open bins: discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: slightly above average open-bin cost,
        // but attractive when item is large and no open bin fits well.
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let mut nb = 6.0 + (open_bins_count as f64) * 0.4;
        nb -= 20.0 * large_item * large_item;
        if fitting_bins_count == 0 {
            nb -= 100.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            nb -= 8.0; // fresh bin can host the next item too
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
