pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_norm = pr / cap;

    // Base: post residual, non-linearly shaped.
    let mut score = pr;

    // Smooth polynomial coupling of residual fill with stream progress:
    // later in the stream, tighter fits (small post_residual) matter more.
    let tightness = 1.0 - fit_norm; // how full the bin becomes
    let coupling = tightness * tightness * (progress * progress * (3.0 - 2.0 * progress));
    score -= 40.0 * coupling * pr / cap;

    // Penalize dead space: residuals too small for likely future items.
    let dead = (pr / cap).powi(3);
    score += 25.0 * dead * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - fit_norm);
    }

    // Discourage opening new bins when open bins exist and fit is decent,
    // more strongly early in the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap);
        } else {
            score += 5.0 * (-gap / cap);
        }
    }

    // Mild dispersion penalty: prefer bins near the mean residual.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Slight preference for consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64 / (1.0 + fit_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual via integer division thresholds
    let post = post_residual;
    if post == 0 {
        score -= 30.0; // perfect closure
    } else if post <= 10 {
        score -= 18.0; // near-perfect
    } else if post <= 20 {
        score -= 8.0;
    } else if post <= 30 {
        score -= 2.0;
    } else {
        // dead-space penalty grows for large unusable gaps
        score += (post as f64) * 0.35;
    }

    // Modulo arithmetic on post_residual: residues that pair well with typical items
    // (items 1..100, so small odd residues 1..=10 are hard to reuse)
    let m = post % 10;
    if post > 0 && m > 0 && m <= 3 {
        score += 6.0; // awkward sliver residue
    } else if m == 0 {
        score -= 3.0; // round residue, easy to fill
    }

    // Harmonic class via quarter capacity fractions of residual
    let quarter = (4 * bin_residual) / bin_capacity; // 0..4
    match quarter {
        0 => score -= 5.0,  // nearly full bin: keep filling it
        1 => score -= 2.0,
        2 => score += 1.0,
        _ => score += 3.0,  // nearly empty bin: deprioritize, save for big items
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack * 0.2);
        } else {
            // next item won't fit here: mild penalty for wasting this slot
            score += 4.0;
        }
    }

    // Last-chance bonus: only one open bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive for very large items or many open bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        score += 20.0 - big_item_bonus - 10.0 * progress - (open_bins_count as f64 * 0.3);
        if item_size > bin_capacity / 2 {
            score -= 8.0; // big item deserves fresh bin
        }
    }

    // Prefer filling bins below mean residual (compress variance)
    score -= (mean_residual - post as f64).max(-10.0).min(10.0) * 0.15;

    // Slight preference for bins whose residual is just above item (minimal waste)
    let waste = (bin_residual - item_size) as f64;
    score += waste * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64; // smallest item possible
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 25.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving a gap just below the next item (blocks lookahead item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += ((next_item_size - post_residual) as f64) * 1.5;
    }

    // Reward bins that can also fit the lookahead item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bins pressure: prefer already-open bins over opening new ones,
    // scaled by how crowded the bin already is.
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * fill_frac);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Slight stream-progression pressure to consolidate early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- 2-step lookahead: how well does post_residual pair with next item? ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        if post_residual == next_item_size {
            // Perfect pairing: next item exactly fills this bin afterwards.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward closeness of the pair-fit.
            let slack_after_pair = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack_after_pair / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize proportional to the overshoot,
            // but soften when post_residual is tiny (already a near-full bin).
            let overshoot = nxt - post;
            score += 0.6 * overshoot * (1.0 - post / bin_capacity as f64);
        }
    } else {
        // Last item in stream: just prefer tightest fit (base score handles it).
        score -= 5.0;
    }

    // ---- Dead-space penalty: residual too small to ever be useful ----
    // Anything below the minimum item size (1) is dead; small residuals (<10)
    // are unlikely to be filled by typical items.
    if post_residual < 10 {
        score += 8.0 * (10 - post_residual) as f64;
    }

    // ---- Last-chance bonus: if this is the only bin that fits, avoid opening new ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; only wins when existing fits are poor.
        score = bin_capacity as f64 - 15.0;
        // If next item is large and current post-fit is bad, opening new is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0;
        }
        // Late in the stream, discourage spawning bins (fewer chances to close them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // ---- Mild context coupling with mean residual ----
    // Prefer bins whose residual is below average (tighter bins) when they fit well.
    score += 0.05 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // ---- Prefer filling fuller bins slightly more as stream progresses ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let cap = bin_capacity as f64;
    let fit_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else {
            score += 5.0 * (1.0 - (post_residual as f64) / cap);
        }
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let mean_fit = if mean_residual >= item_size as f64 { 1.0 } else { 0.0 };
    if open_bins_count > 3 && mean_fit > 0.0 {
        score -= 4.0 * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate: only attractive when no open bin fits or residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity - item_size) as f64).abs();
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fragmentation > 20.0 && open_bins_count > 2 {
            score -= 8.0;
        } else {
            score += 18.0; // keep existing bins alive when they fit reasonably
        }
    }

    // Slight preference for bins whose residual is closest above item_size.
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
