    let norm_item = item_size as f64 / cap;

    // Base: post residual, mildly discounted early (fill bins tightly from start)
    let mut score = pr * (1.0 - 0.25 * progress);

    // Non-linear polynomial coupling: quadratic dead-space penalty grows with progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic interaction between residual and item size: prefer items that leave
    // residuals near "useful" sizes; penalize awkward mid-size leftovers smoothly
    let awkward = (norm_pr - 0.5) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 30.0 * awkward * (1.0 + progress);

    // Lookahead coupling: reward residuals that can still hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 + 6.0 * (1.0 - (nxt / cap));
        } else {
            // penalize residuals just below next item size (smooth ramp)
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: neutral-ish score, slightly worse as open bins fill well
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.15 * progress);
        if fitting_bins_count > 0 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Mean-residual alignment: prefer bins close to mean (balanced packing)
    score += 0.3 * (mean_residual - pr).abs();

    score
}

