pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact capacity fractions are "good" residuals.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Reward residuals that are exact harmonic fractions of capacity (0, 1/4, 1/2, 3/4).
    let harmonics = [0.0f64, 0.25, 0.5, 0.75];
    let mut harm_bonus = 0.0f64;
    for &h in &harmonics {
        let d = (frac - h).abs();
        if d < 0.02 {
            harm_bonus = 12.0 * (1.0 - d / 0.02);
        }
    }
    score -= harm_bonus;

    // Integer-division threshold: leftover classes by post_residual / 10.
    let leftover_class = post_residual / 10;
    match leftover_class {
        0 => score -= 8.0,        // near-perfect fill
        1 => score += 2.0,        // small dead space
        2 | 3 => score -= 1.0,    // usable mid residual
        4 | 5 => score -= 4.0,    // half bin free: very reusable
        _ => {}
    }

    // Modulo-10 coupling between post_residual and next_item_size:
    // if the next item divides the leftover evenly, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size.max(1);
        if rem == 0 {
            score -= 10.0;
        } else if rem <= 3 {
            score -= 4.0;
        } else if rem > next_item_size / 2 {
            score += 3.0; // next item would leave an awkward remainder
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; leftover becomes dead space unless small
        score += (post_residual as f64).min(20.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is bad.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 25.0;
        // open it if existing bins are fragmented and this item is large
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // keep space for a big follower
        }
    }

    // Late in stream: prefer tighter packs, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress * (post_residual as f64 / cap);

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
