        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item can still fit here afterwards: moderate reward scaled by closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover: penalize dead space, worse if large gap.
            score += 0.5 * diff;
        }
