        // it's becoming unusable; penalize proportionally.
        let mean_gap = post_residual as f64 - mean_residual;
        if mean_gap < 0.0 {
            score += 0.3 * (-mean_gap);
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost so it is only chosen
    // when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Many open bins: discourage adding more.
        score += 2.0 * open_bins_count as f64;
    }

