    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 * (-tightness).exp();

    // Penalize large dead space that nothing (especially the lookahead item) can use.
    if post_residual > 0 {
        let waste = if (next_item_size as u32) > post_residual { 1.0 } else { 0.35 };
        score += waste * (post_residual as f64).powf(1.3) * 0.05;
    }

    // Bonus if the next item can exactly fill the resulting residual (perfect chaining).
    if next_item_size > 0 && next_item_size as u32 == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current stream is early (long horizon ahead) and the fit here is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 0.4 * bin_capacity as f64;
        if poor_fit && progress < 0.7 {
            score -= 6.0 + 4.0 * (1.0 - progress);
        } else {
            score += 10.0;
        }
    }

    // Mild pressure to consolidate: when many bins are open, favor filling
    // bins below the mean residual (the emptier ones) less aggressively.
    if open_bins_count > 1 {
        let rel = bin_residual as f64 - mean_residual;
        score += 0.02 * rel * (open_bins_count as f64).ln();
    }

    // Late in the stream, tighten up: avoid leaving any residual that could
    // never be reused by typical item sizes.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && post_residual > 0 {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth polynomial coupling: post_residual scaled by progress-dependent exponent
    let x = pr / cap; // normalized post residual in [0,1]
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like
