    // Penalize large dead space more aggressively as stream progresses
    score += progress * pr * pr / cap;

    // Reward tight fits (small post_residual) especially with lookahead knowledge
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // next item can fit here too: reward chaining
            score -= (nxt / cap) * (1.0 - progress) * 8.0;
        } else {
            // dead space penalty scaled by unusable gap
            score += ((nxt - pr) / cap) * 6.0;
