    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 - progress);
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.15;

    // Mean residual coupling: prefer bins near the mean to keep balance
    score += ((pr - mean_residual) / cap).abs() * 4.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

