        20..=29 => score -= 6.0,
        30..=39 => score -= 3.0,
        40..=49 => score += 1.0,
        50..=59 => score += 3.0,
        60..=79 => score += 5.0,
        _ => score += 7.0,                        // near-empty bin, wasteful placement
    }

    // Integer-division threshold: how many "typical" small items (size 10) fit after placement.
    let slots = post_residual / 10;
    score -= slots as f64 * 2.0;

    // Lookahead coupling: reward residuals that can also host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64) * 0.05;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead-end for the next item: penalize proportionally to leftover
        score += (next_item_size - post_residual) as f64 * 0.08;
