            // Next item cannot use this residual: penalize proportionally
            // to how much wasted potential this bin has.
            score += 3.0 * (next_item_size as f64 - pr as f64) / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin gets a mild penalty so it is
    // only chosen when all open bins fit poorly, but gets a bonus late in
    // the stream or when open-bin residuals are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 10.0 - 8.0 * progress - 6.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 20.0; // no alternative: must use it
        }
    }

    // Prefer packing into bins below the mean residual (tighter bins),
    // keeping loose bins available for big future items.
    let res_frac = bin_residual as f64 / cap;
    let mean_frac = (mean_residual / cap).clamp(0.0, 1.5);
    if res_frac < mean_frac {
        score -= 4.0 * (mean_frac - res_frac);
    } else {
        score += 2.0 * (res_frac - mean_frac);
    }

    // Integer-division threshold: post_residual in [20, 40) is a "medium
    // class" that most mid-size items can still use; mild reward.
    if (20..40).contains(&pr) {
        score -= 3.0;
    }
    // Very large residual with small item: wasteful pairing.
    if pr > 60 && item_size < 20 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
