    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space quality
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Small post-residuals are good; large ones are dead space
    if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    } else if post_residual >= 50 {
        score += 15.0;
    }

    // Modulo-class logic: residuals that are multiples of common item sizes
    // (small items 1..=10) are reusable -> reward
    let small_class = post_residual % 10;
    if small_class == 0 && post_residual > 0 {
        score -= 8.0; // residual is a clean multiple of 10, likely reusable
    } else if small_class <= 3 {
        score -= 2.0;
    } else if small_class >= 7 {
        score += 4.0; // awkward remainder
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
