    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement (creates a full bin).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
