    score += (post_residual as f64).powf(1.8) * 0.05;

    // Fill ratio bonus: the fuller the bin becomes, the better.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 25.0;

    // Penalize creating dead space: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // awkward zone
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        // If the NEXT item also fits in the leftover, extra reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Lookahead: penalize placements that leave a residual which neither fits
    // the next item nor is cleanly reusable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // chain placement possible
        } else {
            score += 6.0;  // next item will need another bin anyway
        }
    }

    // New-bin candidate handling: an empty bin is attractive only when open
    // bins are crowded or the current fit is poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64; // average openness
        let crowding = (open_bins_count as f64).ln().max(0.0);
        // Base cost of opening a new bin, discounted under crowding/pressure.
        let mut open_cost = 40.0 - crowding * 6.0 - pressure * 25.0;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        open_cost += progress * 25.0;
        // If the item would leave a bad residual in any open bin, opening is fine.
        if post_residual < 10 && bin_residual == bin_capacity {
            open_cost -= 15.0;
        }
        score += open_cost.max(-30.0);
    }

    // Global balance: prefer bins whose residual is near the mean residual
    // after placement (keeps the pool homogeneous and packable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for using existing bins vs. many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

