pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Progress-dependent weighting of dead space (later in stream => penalize more)
    let w = 0.5 + 1.5 * progress * progress;
    score += w * pr_norm * pr_norm * cap * 0.2;

    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize leaving residual close to next item size mismatch (smooth interaction)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.05 * diff * diff / cap;
    }

    // Last-chance bonus: smooth reward when few fitting bins
    let fit_frac = 1.0 / (fitting_bins_count as f64);
    score -= 8.0 * fit_frac * fit_frac * (0.3 + 0.7 * progress);

    // Mild penalty for spreading across many open bins late in stream
    score += 0.01 * (open_bins_count as f64) * progress;

    // Mean residual alignment: prefer bins near mean residual
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    score
}

