pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "nice" slots
    // (small remainders mod common item-size classes: 10, 20, 25, 50).
    let pr = post_residual as i64;
    let nice = |m: i64| -> f64 {
        if pr % m == 0 { 0.0 } else { let r = pr % m; (m - r) as f64 * 0.6 }
    };
    score += nice(10) * 0.5 + nice(20) * 0.4 + nice(25) * 0.3 + nice(50) * 0.5;

    // Lookahead harmony: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 30.0;
        } else if next_item_size as u32 <= post_residual {
            // reward proportional to how much next item fills the leftover
            score -= 8.0 * (n / (post_residual as f64 + 1.0));
        } else {
            // dead space penalty scaled by how badly next item misses
            let miss = n - post_residual as f64;
            score += (miss * 0.4).min(15.0);
        }
        // Harmonic coupling: next item divisible by 10 pairs well with divisible post_residual
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves
    // a truly unusable sliver (post_residual too small for typical items).
    if bin_residual == bin_capacity {
        let unusable = post_residual > 0 && (post_residual as f64) < cap * 0.1;
        if unusable || open_bins_count == 0 {
            score -= 25.0; // fresh bin is fine / necessary
        } else {
            score += 20.0; // prefer existing bins generally
        }
    }

    // Slight preference for tighter bins early in stream (mean residual coupling)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.05 * (1.0 - progress);

    // Small penalty for very tiny dead space (wasted capacity)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

