pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 5.0 * post_residual as f64; // worst for tiny gaps
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 80.0; // perfect fit strongly rewarded
    }

    // Reward bins whose residual is "consumed" proportionally well.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Lookahead coupling: if next item fits the post-residual, favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 10.0; // dead space for the known next item
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, keep fills tight.
    let pressure = open_bins_count as f64 / (1.0 + (total_items as f64).max(1.0) / 50.0);
    score += 8.0 * pressure * (1.0 - fill_ratio);

    // Mean-residual alignment: prefer bins near the mean residual (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 90.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = -20.0; // forced to open
        } else if fitting_bins_count == 1 {
            new_bin_penalty = 30.0;
        }
        // Late in stream, new bins are cheaper to open early for large future items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty -= 20.0 * (1.0 - progress);
        if next_item_size > item_size {
            new_bin_penalty -= 15.0; // big item coming, fresh bin may help
        }
        score += new_bin_penalty;
    }

    score
}

