pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but treat dead space super-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.35;
    } else {
        // Perfect fill is excellent.
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let gap = post_residual as f64 - next;
            // Reward closeness of next item to fill the leftover space.
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 12.0; // exact 2-item completion
            }
        } else {
            // Next item cannot use the leftover: penalize proportionally to waste.
            score += 6.0 + 0.25 * (next - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce/special.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        // This bin is tighter than average: placing here preserves loose bins.
        score -= 0.08 * dev;
    } else {
        // This bin is looser than average: discourage dumping small items here.
        score += 0.05 * (-dev);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64).min(1.0)
        } else {
            0.5
        };
        // Penalize opening new bins; relax penalty late in stream or under many open bins.
        score += 30.0 - 10.0 * pressure - 0.02 * open_bins_count as f64
                 - 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference for consolidating when many bins are open.
    score -= 0.01 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

