    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + progress) * 12.0;

    // Last-chance bonus: strongly favor the only fitting bin, scaled by progress
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // Scarcity pressure: many open bins -> mild penalty for spreading residual badly
    score += (open_bins_count as f64).ln() * pr_norm * 2.0;

    // Mean residual coupling: penalize bins far below mean residual (waste of usable space)
    score += ((mean_residual - pr).abs()) * 0.15 * (0.5 + progress);

