        if r1 > next_item_size {
            let tail = r1 - next_item_size;
            if tail <= 10 { score -= 14.0 - tail as f64; }
        }
    }
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.6 {
        score += post_residual as f64 * 0.15 * (progress - 0.6) * 2.5;
    }
    if post_residual > 0 {
        let diff = (post_residual as f64 - mean_residual).abs();
        score -= 4.0 * (1.0 - (diff / bin_capacity as f64).min(1.0));
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let regret = (next_item_size - post_residual) as f64;
        if regret <= 12 { score += 12.0 - regret * 0.5; }
    }
    // refined dead-space coupling: penalize residuals that are useless for the near future
    if post_residual > 0 && next_item_size > 0 {
        let useless = (post_residual as f64 / next_item_size as f64).min(1.0);
        if post_residual < next_item_size {
            score += (1.0 - useless) * 6.0 * (0.5 + progress);
        }
    }
    // two-item lookahead: reward bins that could hold item + next item exactly
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let r2 = bin_residual - item_size - next_item_size;
        if r2 <= 6 { score -= 10.0 - r2 as f64; }
    }
    // late-stage compaction: prefer filling nearly-full bins more aggressively
    if progress > 0.7 && post_residual > 0 && post_residual <= item_size.max(next_item_size) {
        score -= 8.0 * (progress - 0.7) * 3.0;
    }
    // dead-space avoidance: penalize residuals that can never be useful again
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 5.0 + 4.0 * (1.0 - post_residual as f64 / item_size.max(next_item_size) as f64);
    }
    // reward exact-fill trajectories: post residual equal to a plausible future small item
    if post_residual > 0 && post_residual <= 10 && next_item_size <= post_residual {
        score -= 9.0;
    }
    // mid-stream variance control: keep residuals homogeneous when many bins are open
    if open_bins_count > 8 && post_residual > 0 {
        let spread = (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;
        score += 3.0 * spread * (1.0 - progress);
    }
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on fine-grained
    // "usable" classes are rewarded; coarse dead-space classes are penalized.
    let class = post_residual % 10;
    match class {
        0 => score -= 8.0,                       // perfectly reusable leftover
        1 | 2 | 3 => score -= 3.0,               // small but still useful
        4 | 5 | 6 => score += 2.0,               // mediocre dead space
        _ => score += 5.0,                       // large awkward leftover
    }

    // Integer-division threshold: reward leaving room for typical next items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 {
        // leftover too small for the lookahead item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Capacity-fraction coupling: prefer filling bins past key fractions.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_frac >= 0.9 {
        score -= 10.0;
    } else if fill_frac >= 0.7 {
        score -= 4.0;
    } else if fill_frac < 0.5 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bin would waste a lot.
    if bin_residual == bin_capacity {
        score += (bin_capacity - post_residual) as f64 * 2.0
            + (post_residual as f64) * 0.5
            - (open_bins_count as f64).sqrt() * 2.0;
    }

    // Slight preference for tighter bins overall (mean residual coupling).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Late-stream squeeze: reduce open-bin sprawl near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
