    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for even the smallest
    // item (1..10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 200.0;
    } else if post_residual < 20 {
        // Gaps below 20 are hard to fill; scale penalty by gap smallness.
        score += (20 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    score -= (item_size as f64 / (item_size + post_residual) as f64) * 30.0;

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when open_bins_count is large.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 40.0 + pressure * 2.0;
    } else {
        // Reward using existing bins, scaled by pressure.
        score -= pressure * 0.8;
    }

    // Last-chance bin: strongly favor filling the only fitting bin to avoid
    // opening a new one for a poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: post residual becomes dead space risk.
        score += post_residual as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (filling the emptier-but-fitting bins wastes less future capacity).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the new residual,
    // penalize when next item leaves a large mismatch.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain: this bin becomes perfect for next item
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.5; // leftover after next item
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3; // next item can't use this bin
        }
    }

    // Penalize small unusable dead space (below typical minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Compare residual against mean residual: prefer bins that will be
    // tightly packed relative to the fleet average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Late in the stream, avoid opening new bins: penalize the fresh-bin candidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 + 150.0 * progress;
    }

    // Mild preference for filling already-open bins when many are open.
    score += open_bins_count as f64 * 0.1 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual is good, but a tiny nonzero
    // remainder (< 10) is nearly unusable, so reward exact/near-exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight-fit reward: item occupying most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement (chain packing); otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            // placing here forces next item elsewhere; mild penalty
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: prefer the tightest, already handled by fill_ratio
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: many open bins with slack -> encourage consolidating
    // into existing bins rather than opening new ones.
    let avg_slack = mean_residual - post_residual as f64;
    score += 0.05 * open_bins_count as f64;
    score += 0.08 * avg_slack;

    // Time horizon: early in the stream, be more willing to open new bins
    // (preserve flexibility); late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 20.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= new_bin_bias;
        // But if current bins are nearly full on average, a new bin is fine.
        score -= 0.1 * mean_residual;
    } else {
        score += new_bin_bias * 0.3;
    }

    // Discourage placing small items into large residuals (waste of space).
    if item_size < 30 && bin_residual > 70 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
