pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial shaping
    let mut score = pr;

    // Non-linear polynomial coupling of normalized post_residual with progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + progress);

    // Penalize large dead space more aggressively as stream progresses
    let dead = norm_pr * norm_pr * norm_pr;
    score += 30.0 * dead * (0.3 + 0.7 * progress);

    // Tight fits are valuable: smooth reward for post_residual near zero
    let tight = (-norm_pr * 8.0).exp();
    score -= 12.0 * tight * (1.0 + progress);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward if next item fits in post_residual (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        let bonus = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 10.0 * bonus * (1.0 - fits) * (1.0 - fits);
        // Penalize leaving space that neither fits next item nor is useful
        let waste = if pr < nxt { (nxt - pr) / cap } else { 0.0 };
        score += 8.0 * waste * waste * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins vs consolidation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Mean residual coupling: prefer bins near the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: keep it slightly attractive early, discourage late
    if bin_residual == bin_capacity {
        score += 15.0 * progress - 5.0 * (1.0 - progress);
    }

    score
}

