    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify dead space into
    // capacity fractions (small slivers are near-useless, large residuals reusable).
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Class boundaries via integer division on post_residual (harmonic classes of C/2^k)
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward residuals that still belong to "usable" harmonic classes.
    if post_residual > half {
        score -= 25.0; // class 1: very reusable
    } else if post_residual > quarter {
        score -= 12.0; // class 2
    } else if post_residual > eighth {
        score -= 4.0; // class 3
    } else {
        score += 15.0; // sliver: dead space penalty
    }

    // Perfect-fill harmonic classes: residual exactly divides into common item sizes
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0; // aligned to smallest item granularity
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 2.0; // unaligned leftover
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item's class vs residual class
            let nx = next_item_size as f64;
            let tight = (post - nx) / cap;
            score -= 20.0 * (1.0 - tight); // tight lookahead fit strongly favored
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0; // residual divisible by next item: harmonic chain
            }
        } else {
            score += 10.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good harmonic fit exists.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).sqrt();
        // Penalize new bin mildly; escalate late in the stream when consolidation matters.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 + 10.0 * pressure * (0.5 + progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // pairing big-then-bigger in fresh bin is fine
        }
        if item_size > half {
            score -= 25.0; // big items deserve fresh bins
        }
    }

    // Mild bias toward fuller bins overall (reduce fragmentation across fleet).
    score -= 0.05 * (cap - post) ;

    // Mean-residual divergence: prefer bins near the fleet mean to keep classes uniform.
    score += 0.10 * (post - mean_residual).abs();

    score
}

