pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0 * (10.0 - dead); // tiny gaps become very costly
    } else if dead >= 10.0 && dead < 25.0 {
        score += 0.8 * (25.0 - dead); // moderate penalty for small-ish gaps
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Perfect-fit lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Penalize if next item cannot fit in post_residual (dead space locked in),
    // scaled by how large the gap is.
    if next_item_size > post_residual && post_residual > 0 {
        score += 1.5 * (next_item_size as f64 - post_residual as f64).min(post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

