    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let regret = (next_item_size - post_residual) as f64;
        if regret <= 12 { score += 12.0 - regret * 0.5; }
    }
    // useless-residual coupling: penalize residuals that can't serve the next item
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
