    }
    if post_residual > 0 && post_residual == item_size + next_item_size {
        score -= 15.0;
    }
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits; late in the stream, tolerate larger post_residual
    // since future correction opportunities are scarce.
    let coupling = norm_post * norm_post * (1.0 - progress) * 40.0
                 + norm_post * progress * 15.0;
    score += coupling;

    // Reward near-perfect fits with a smooth quadratic bonus.
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 25.0;

    // Penalize when this is the only fitting bin but fit is poor (last-chance pressure).
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_post);
    }

    // Smooth lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0) / cap;
        let gap = (post - nxt).abs() / cap;
        score -= fits_next * (1.0 - gap) * 20.0;
        score += gap * gap * 10.0;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += (open_bins_count as f64) * 0.05 * (mean_residual / cap - norm_post).abs();

    score
}

