    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 as fine-grain penalty,
    // coarse classes via integer division of capacity.
    let pr = post_residual as u32;
    let fine = pr % 10;
    let coarse = pr / 10;

    // Dead-space penalty: residual that is too small for any plausible item
    // (items >= 1, so residual 0 is perfect; small but nonzero residual is waste).
    if pr > 0 {
        score += (10 - fine) as f64 * 0.35;          // prefer residuals landing on multiples of 10
        if pr < 10 {
            score += 12.0;                            // tiny unusable sliver
        }
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's remainder; penalize large leftover
            score += (pr as f64) * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins deviating below the mean (tighter packing)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Stream progression: late in the stream, be more conservative with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above using an existing decent fit
        score = cap * 0.55 - 18.0 * progress + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // room for a natural pair in a fresh bin
            score -= 15.0;
        }
