        score += 40.0 + 65.0 * (1.0 - pressure) * tight - 30.0 * hard * pressure;
        if fitting_bins_count > 0 {
            let best_waste = post_residual.min(item_size) as f64;
            if best_waste < bin_capacity as f64 * 0.06 { score += 30.0; }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.55 && fitting_bins_count > 0 {
            score += 20.0 * (progress - 0.55) * 2.0;
        }
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < item_size {
        score += 14.0;
    }
    let dead = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 {
        if dead < 0.1 {
            score -= 6.0 * (0.1 - dead) * 10.0;
        } else if dead > 0.5 && next_item_size > 0 && post_residual < next_item_size {
            score += 18.0 * (dead - 0.5);
        } else if dead > 0.35 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * (dead - 0.35) * (0.5 + progress);
        }
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 25.0; }
    if post_residual > 0 && post_residual == item_size.min(bin_residual) && bin_residual >= item_size {
        score -= 8.0;
    }
    if next_item_size > 0 && bin_residual >= item_size {
        let r1 = bin_residual - item_size;
        if r1 > next_item_size {
            let tail = r1 - next_item_size;
            if tail <= 10 { score -= 14.0 - tail as f64; }
        }
    }
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.6 {
        score += post_residual as f64 * 0.15 * (progress - 0.6) * 2.5;
    }
    if post_residual > 0 {
        let diff = (post_residual as f64 - mean_residual).abs();
        score -= 4.0 * (1.0 - (diff / bin_capacity as f64).min(1.0));
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let regret = (next_item_size - post_residual) as f64;
        if regret <= 12 { score += 12.0 - regret * 0.5; }
    }
    // refined dead-space coupling: penalize residuals that are useless for the near future
    if post_residual > 0 && next_item_size > 0 {
        let useless = (post_residual as f64 / next_item_size as f64).min(1.0);
        if post_residual < next_item_size {
            score += (1.0 - useless) * 6.0 * (0.5 + progress);
        }
    }
    // two-item lookahead: reward bins that could hold item + next item exactly
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let r2 = bin_residual - item_size - next_item_size;
        if r2 <= 6 { score -= 10.0 - r2 as f64; }
    }
    // late-stage compaction: prefer filling nearly-full bins more aggressively
    if progress > 0.7 && post_residual > 0 && post_residual <= item_size.max(next_item_size) {
        score -= 8.0 * (progress - 0.7) * 3.0;
    }
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;
    // NEW: residual granularity — reward post_residuals that are small "usable" slices
    // (multiples of common small item sizes keep future fit probability high)
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr <= 20.0 {
            score -= 5.0 * (1.0 - pr / 20.0) * (0.6 + 0.4 * progress);
        }
        // penalize awkward mid-range residuals unlikely to be exactly filled
        if pr > 20.0 && pr < 60.0 {
            let awkward = ((pr - 40.0) / 20.0).abs();
            score += 3.0 * awkward * (0.5 + progress);
        }
    }
    // NEW: residual fragmentation guard — when many bins fit, prefer the one whose
    // post_residual best matches the mean residual (keeps pool homogeneous)
    if post_residual > 0 && fitting_bins_count > 3 {
        let diff = (post_residual as f64 - mean_residual).abs();
        if diff < mean_residual * 0.15 { score -= 5.0; }
        else if diff > mean_residual * 0.6 { score += 4.0; }
    }
    // NEW: endgame squeeze — in the final stretch, waste tolerance drops sharply
    if progress > 0.85 && post_residual > 0 {
        score += post_residual as f64 * 0.25 * (progress - 0.85) * 4.0;
    }
    score
}

