pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Slight penalty if next item cannot fit after this placement (dead-end chain).
        if next_item_size > post_residual {
            score += 6.0;
        }
    } else {
        // Last item: prefer minimal waste directly.
        score -= 10.0;
    }

    // Penalize leaving residual far below mean (fragmentation) but reward tight fits.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.25 * (mean_residual - pr).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Discard nearly-full residual waste: tiny unusable leftovers are fine,
    // but mid-range dead space is bad (non-linear coupling).
    if pr > 0.0 && pr < 10.0 {
        score -= 5.0; // small scraps are acceptable
    } else if pr >= 10.0 && pr < 25.0 {
        score += 4.0; // awkward dead zone
    }

    // New-bin candidate: prefer reusing open bins unless this is a poor fit;
    // make the empty bin mildly unattractive so it wins only on big items.
    if bin_residual == bin_capacity {
        score += 8.0;
        // For very large items, opening a fresh bin is often better.
        if item_size >= bin_capacity / 2 {
