    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing bins rather than spreading.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Time horizon: early in stream, encourage compact packing; later, be more permissive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

