    // (consolidate), else prefer bins above mean (spread the slack).
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.05;

    // New-bin candidate logic: an empty bin is only attractive when the item is
    // large or no good alternative exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.75 {
