    score -= 3.0 * (open_bins_count as f64 / (total_items as f64 + 1.0)).sqrt() * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - norm_item) * (1.0 - progress);
