    // Harmonic class of post_residual: residual classes mod 10.
    // Small post_residual classes are "good" (tight fills); large ones are dead space.
    let cls = (post_residual % 10) as f64;
    score -= 0.6 * cls;                       // reward high tens, penalize awkward class
    if post_residual % 10 == 0 {
        score -= 4.0;                          // perfectly aligned residual is ideal
    }
    if post_residual % 20 == 0 {
        score -= 2.0;                          // half-capacity-aligned residual
    }
    if post_residual % 5 != 0 {
        score += 1.5;                          // odd-class residuals are hard to reuse
    }

    // Integer-division thresholds on post_residual.
    let q = post_residual / 10;                // how many 10-sized items still fit
    if q == 0 {
        score += 8.0;                          // nearly dead space (<10)
    } else if q == 1 {
        score -= 1.0;                          // exactly one small item fits: efficient
    }

    // Coupling with lookahead item: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;                      // chain-friendly placement
            // harmonic match: next item exactly consumes a residual class
            if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
                score -= 3.0;
            }
        } else {
            score += 3.0;                      // next item won't chain here
        }
    } else {
        score += 0.0;                          // last item: pure fill, base score fine
    }

