    // Perfect fill: exact match ends the bin cleanly.
    if post_residual == 0 { score -= 1000.0; }

    // Strong lookahead chain rewards.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 560.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.6;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3 + if gap > 25.0 { gap * 0.18 } else { 0.0 };
        }
    }

    // Slight fill-level preference.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Reward near-perfect two-item chains.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin decision: only open fresh bins when fits are genuinely poor.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = item_size as f64 / bin_capacity as f64;
        let tight = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let frag = (fitting_bins_count as f64 / open_bins_count.max(1) as f64).clamp(0.0, 1.0);
        let hard = 1.0 - frag;
        score += 40.0 + 65.0 * (1.0 - pressure) * tight - 30.0 * hard * pressure;
        if fitting_bins_count > 0 {
            let best_waste = post_residual.min(item_size) as f64;
            if best_waste < bin_capacity as f64 * 0.06 { score += 30.0; }
        }
        if progress > 0.55 && fitting_bins_count > 0 {
            score += 20.0 * (progress - 0.55) * 2.0;
        }
    }

    // Penalize residuals the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < item_size {
        score += 14.0;
    }

    // Dead-space shaping.
    let dead = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 {
        if dead < 0.1 {
            score -= 6.0 * (0.1 - dead) * 10.0;
        } else if dead > 0.5 && next_item_size > 0 && post_residual < next_item_size {
            score += 18.0 * (dead - 0.5);
        } else if dead > 0.35 {
            score += 10.0 * (dead - 0.35) * (0.5 + progress);
        }
    }

