    // common item sizes (multiples of 10/5), making space reusable.
    if mod10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if mod5 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Odd residues (mod 3) are awkward; slight penalty.
    if mod3 == 1 {
        score += 2.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; penalize by how wasted the space is
            score += next_item_size as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: baseline so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
