        if next_item_size > item_size {
            score -= (next_item_size - item_size) as f64 * 0.2;
        }
    }

    // Prefer tighter bins overall (below mean residual).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

