    } else if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.3 + if gap > 25.0 { gap * 0.18 } else { 0.0 };
    }
    score += (bin_capacity - bin_residual) as f64 * 0.05;
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = item_size as f64 / bin_capacity as f64;
        let tight = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let frag = (fitting_bins_count as f64 / open_bins_count.max(1) as f64).clamp(0.0, 1.0);
        let hard = 1.0 - frag;
        score += 40.0 + 65.0 * (1.0 - pressure) * tight - 30.0 * hard * pressure;
        if fitting_bins_count > 0 {
            let best_waste = post_residual.min(item_size) as f64;
            if best_waste < bin_capacity as f64 * 0.06 { score += 30.0; }
        }
        if progress > 0.55 && fitting_bins_count > 0 {
            score += 20.0 * (progress - 0.55) * 2.0;
        }
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < item_size {
        score += 14.0;
    }
    let dead = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 {
        if dead < 0.1 {
            score -= 6.0 * (0.1 - dead) * 10.0;
        } else if dead > 0.5 && next_item_size > 0 && post_residual < next_item_size {
            score += 18.0 * (dead - 0.5);
        } else if dead > 0.35 {
            score += 10.0 * (dead - 0.35) * (0.5 + progress);
        }
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 25.0; }
    if post_residual > 0 && post_residual == item_size.min(bin_residual) && bin_residual >= item_size {
        score -= 8.0;
    }
    if next_item_size > 0 && bin_residual >= item_size {
        let r1 = bin_residual - item_size;
        if r1 > next_item_size {
            let tail = r1 - next_item_size;
            if tail <= 10 { score -= 14.0 - tail as f64; }
        }
    }
    if progress > 0.6 {
        score += post_residual as f64 * 0.15 * (progress - 0.6) * 2.5;
    }
    if post_residual > 0 {
        let diff = (post_residual as f64 - mean_residual).abs();
        score -= 4.0 * (1.0 - (diff / bin_capacity as f64).min(1.0));
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let regret = (next_item_size - post_residual) as f64;
        if regret <= 12 { score += 12.0 - regret * 0.5; }
    }
    // refined dead-space coupling: penalize residuals useless for the near future
    if post_residual > 0 && next_item_size > 0 {
        let useless = (post_residual as f64 / next_item_size as f64).min(1.0);
        if post_residual < next_item_size {
            score += (1.0 - useless) * 6.0 * (0.5 + progress);
        }
    }
    // two-item lookahead: reward bins that could hold item + next item exactly
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let r2 = bin_residual - item_size - next_item_size;
        if r2 <= 6 { score -= 10.0 - r2 as f64; }
    }
    // late-stage compaction: prefer filling nearly-full bins more aggressively
    if progress > 0.7 && post_residual > 0 && post_residual <= item_size.max(next_item_size) {
        score -= 8.0 * (progress - 0.7) * 3.0;
    }
    // NEW: graded dead-space penalty scaled by remaining stream length —
    // waste left in bins early in the stream is costlier than late waste
    if post_residual > 0 {
        let waste = post_residual.min(bin_capacity / 3) as f64;
        score += waste * 0.04 * (1.0 - progress);
    }
    // NEW: reward bins whose post-residual matches the *distribution* of
    // upcoming demand — residual close to mean_residual is reusable space
    if post_residual > 0 && mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if (0.85..=1.15).contains(&ratio) { score -= 5.0; }
    }
    // NEW: small-residual trap avoidance — a post-residual that is very
    // small but nonzero is nearly dead space; penalize proportionally
    if post_residual > 0 && post_residual < 8 && (next_item_size == 0 || next_item_size > post_residual) {
        score += (8 - post_residual) as f64 * 1.5;
    }
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space that no future item can plausibly use.
    // Smallest item is assumed ~1..10; residual below ~10 is nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Post-residual too small for the next item: penalize proportionally.
            score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64) * (mean_residual / (bin_capacity as f64));
    if bin_residual < bin_capacity {
        score -= 0.05 * pressure;
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // item is large relative to capacity or existing bins are very full.
    if bin_residual == bin_capacity {
        let fill_ratio = (item_size as f64) / (bin_capacity as f64);
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for opening a new bin.
        score += 18.0;
        // Attractive when item is big (would leave little residual anyway)
        // or late in the stream where closing out bins matters.
        score -= 30.0 * fill_ratio * fill_ratio;
        score -= 10.0 * time_frac;
        // If the current bin would leave a bad fit, new bin becomes better.
        if post_residual > 0 && post_residual < 15 {
            score -= 12.0;
        }
        // If many bins are open with slack, discourage a new bin.
        score += 0.03 * pressure;
    }

    // Mild time-horizon effect: early in the stream, keep bins tidy
    // (favor balanced residuals); late, just pack greedily.
    let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - time_frac) * ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}
